def transform(grid):
    g=[row[:] for row in grid]
    h=len(g); w=len(g[0]); sep=next(c for c in range(w) if len(set(g[r][c] for r in range(h)))==1)
    shapes={}
    for r in range(h):
        for c in range(sep):
            color=g[r][c]
            if color:
                shapes.setdefault(color,[]).append((r,c))
    mapped=set()
    for color,cells in shapes.items():
        ys=[r for r,c in cells]; xs=[c for r,c in cells]
        top=min(ys); left=min(xs); sh=max(ys)-top+1; sw=max(xs)-left+1
        markers=[c for c in range(sep+1,w) if g[0][c]==color and g[h-1][c]==color]
        sides=[r for r in range(h) if g[r][-1]==color]
        for xc in markers:
            mapped.add(color)
            for yc in sides:
                for r,c in cells:
                    rr=yc-sh//2+r-top; cc=xc-(sw-1)//2+c-left
                    if g[rr][cc]==0: g[rr][cc]=color
    for r in range(h):
        for c in range(sep):
            if g[r][c] in mapped: g[r][c]=0
    return g

